if (!/<h2[\s>][^<]*<\/h2>/i.test(code)) {
  throw new Error("Add an <h2> with the recipe name.");
}

const ulMatch = code.match(/<ul[\s\S]*?<\/ul>/i);
if (!ulMatch) {
  throw new Error("No <ul> found — ingredients go in an unordered list.");
}
const items = (ulMatch[0].match(/<li[\s>]/gi) || []).length;
if (items < 3) {
  throw new Error("The ingredient <ul> needs at least 3 <li> items.");
}

const olMatch = code.match(/<ol[\s\S]*?<\/ol>/i);
if (!olMatch) {
  throw new Error("No <ol> found — steps go in an ordered list.");
}
const items = (olMatch[0].match(/<li[\s>]/gi) || []).length;
if (items < 3) {
  throw new Error("The steps <ol> needs at least 3 <li> items.");
}

const ul = code.match(/<ul[\s\S]*?<\/ul>/i);
const ol = code.match(/<ol[\s\S]*?<\/ol>/i);
if (ul && ol && ul.index < ol.index && /<ol[\s\S]*<\/ul>/i.test(code)) {
  throw new Error("It looks like the ingredient list uses <ol> — use <ul> when order does not matter.");
}
